mapper.select:
SELECT
 *
FROM
 S02M048T
WHERE
 APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
 AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
 AND TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
 AND SRLNO = #{srlno,jdbcType=VARCHAR}
 AND YUKOKBN = '1'

SELECT * FROM ( SELECT '0' AS ITAKUFLG, NVL(TSSM.WSVKISHUCD, '00') AS WSVKISHUCD, TSSM.STUPWSVNO, TSSM.SHNCD, SHMV.SHNNMKIRIKAEDD, SHMV2.SHNNMKIRIKAEDD AS FRONTPANELKIRIKAEDD, SHMV.IRO, SYKM.MOJISETTEIATAI, TSSM.KATASIKI, TSSM.SRLNO, TSSM.STUPDD, TSSM.KONKAIMNTDD, TSSM.JIKAIMNTYTIDYDM, TSSM.MNTKAISU, TSSM.HIKIAGEDD, TSSM.RTLSTRTDD, TSSM.INPTSYSTMYMD, TSSM.INPTSYSTMJIKAN, TSSM.TOSHAAPKIHONCD, TSSM.TOSHASHOPCD, TSSM.TOSHACD, TTSM3.TNSHAMEI AS TOSHAMEI, TSSM.KSHNSYSTMYMD, TSSM.KSHNSYSTMJIKAN, TSSM.KOSHAAPKIHONCD, TSSM.KOSHASHOPCD, TSSM.KOSHACD, TSSM.MEISAIBIKO, DECODE(TSSM.CUPHOLDERUMU,'0','無','1','有','') AS CUPHOLDERNM, -- コンディションマスタの名称は使用しない SYKM2.MOJISETTEIATAI AS LOCKTFOSET, TSSM.PANELNO, SYKM3.MOJISETTEIATAI AS WSVKISHUNM, TTSM4.TNSHAMEI AS KOSHAMEI, SYKM4.MOJISETTEIATAI AS STUPBASYOKBN, TSSM.STUPBASYOBIKO, CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{unyodate,jdbcType=VARCHAR} THEN SHMV.SHINSHNNMRYAKUSHO ELSE SHMV.GENZSHNNMRYAKUSHO END SHNNMRYAKUSHOMEI, CASE WHEN SHMV2.SHNNMKIRIKAEDD <= #{unyodate,jdbcType=VARCHAR} THEN SHMV2.SHINSHNNMRYAKUSHO ELSE SHMV2.GENZSHNNMRYAKUSHO END FRONTPANELMEI FROM S02M048T TSSM JOIN S02V001T SHMV ON TSSM.APKIHONCD = SHMV.APKIHONCD AND TSSM.SHOPCD = SHMV.SHOPCD AND TSSM.SHNCD = SHMV.SHNCD LEFT JOIN S02V001T SHMV2 ON TSSM.APKIHONCD = SHMV2.APKIHONCD AND TSSM.SHOPCD = SHMV2.SHOPCD AND TSSM.FRONTPANELCD = SHMV2.SHNCD LEFT JOIN S02M006T SYKM ON SHMV.SZ = SYKM.SETTEICD AND SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEINO = '037' LEFT JOIN S02M006T SYKM2 ON TSSM.LOCKTFOSET = SYKM2.SETTEICD AND SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEINO = '144' LEFT JOIN S02M003T TTSM3 ON TSSM.TOSHAAPKIHONCD = TTSM3.APKIHONCD AND TSSM.TOSHASHOPCD = TTSM3.SHOPCD AND TSSM.TOSHACD = TTSM3.TNSHACD LEFT JOIN S02M003T TTSM4 ON TSSM.KOSHAAPKIHONCD = TTSM4.APKIHONCD AND TSSM.KOSHASHOPCD = TTSM4.SHOPCD AND TSSM.KOSHACD = TTSM4.TNSHACD LEFT JOIN S02M006T SYKM3 ON TSSM.WSVKISHUCD = SYKM3.SETTEICD AND SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEINO = '145' LEFT JOIN S02M006T SYKM4 ON SYKM4.SETTEICD = TSSM.STUPBASYOKBN AND SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEINO = '184' WHERE TSSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TSSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TSSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} AND TSSM.YUKOKBN = '1' AND TSSM.HIKIAGEDD IS NULL
UNION ALL SELECT '1' AS ITAKUFLG, NVL(TSSM.WSVKISHUCD, '00') AS WSVKISHUCD, TSSM.STUPWSVNO, TSSM.SHNCD, SHMV.SHNNMKIRIKAEDD, SHMV2.SHNNMKIRIKAEDD AS FRONTPANELKIRIKAEDD, SHMV.IRO, SYKM.MOJISETTEIATAI, TSSM.KATASIKI, TSSM.SRLNO, TSSM.STUPDD, TSSM.KONKAIMNTDD, TSSM.JIKAIMNTYTIDYDM, TSSM.MNTKAISU, TSSM.HIKIAGEDD, TSSM.RTLSTRTDD, TSSM.INPTSYSTMYMD, TSSM.INPTSYSTMJIKAN, TSSM.TOSHAAPKIHONCD, TSSM.TOSHASHOPCD, TSSM.TOSHACD, TTSM3.TNSHAMEI AS TOSHAMEI, TSSM.KSHNSYSTMYMD, TSSM.KSHNSYSTMJIKAN, TSSM.KOSHAAPKIHONCD, TSSM.KOSHASHOPCD, TSSM.KOSHACD, TSSM.MEISAIBIKO, CNDM1.ITEMNM AS CUPHOLDERNM, SYKM2.MOJISETTEIATAI AS LOCKTFOSET, TSSM.PANELNO, SYKM3.MOJISETTEIATAI AS WSVKISHUNM, TTSM4.TNSHAMEI AS KOSHAMEI, SYKM4.MOJISETTEIATAI AS STUPBASYOKBN, TSSM.STUPBASYOBIKO, CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{unyodate,jdbcType=VARCHAR} THEN SHMV.SHINSHNNMRYAKUSHO ELSE SHMV.GENZSHNNMRYAKUSHO END SHNNMRYAKUSHOMEI, CASE WHEN SHMV2.SHNNMKIRIKAEDD <= #{unyodate,jdbcType=VARCHAR} THEN SHMV2.SHINSHNNMRYAKUSHO ELSE SHMV2.GENZSHNNMRYAKUSHO END FRONTPANELMEI FROM S02M048T TSSM JOIN S02V001T SHMV ON TSSM.APKIHONCD = SHMV.APKIHONCD AND TSSM.SHOPCD = SHMV.SHOPCD AND TSSM.SHNCD = SHMV.SHNCD LEFT JOIN S02V001T SHMV2 ON TSSM.APKIHONCD = SHMV2.APKIHONCD AND TSSM.SHOPCD = SHMV2.SHOPCD AND TSSM.FRONTPANELCD = SHMV2.SHNCD LEFT JOIN S02M006T SYKM ON SHMV.SZ = SYKM.SETTEICD AND SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEINO = '037' LEFT JOIN S02M006T SYKM2 ON TSSM.LOCKTFOSET = SYKM2.SETTEICD AND SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEINO = '144' LEFT JOIN S02M003T TTSM3 ON TSSM.TOSHAAPKIHONCD = TTSM3.APKIHONCD AND TSSM.TOSHASHOPCD = TTSM3.SHOPCD AND TSSM.TOSHACD = TTSM3.TNSHACD LEFT JOIN S02M003T TTSM4 ON TSSM.KOSHAAPKIHONCD = TTSM4.APKIHONCD AND TSSM.KOSHASHOPCD = TTSM4.SHOPCD AND TSSM.KOSHACD = TTSM4.TNSHACD LEFT JOIN S02M006T SYKM3 ON TSSM.WSVKISHUCD = SYKM3.SETTEICD AND SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEINO = '145' LEFT JOIN S02M006T SYKM4 ON SYKM4.SETTEICD = TSSM.STUPBASYOKBN AND SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEINO = '184' LEFT OUTER JOIN S01M004T CNDM1 ON CNDM1.CONDITIONID = 'CN231' AND CNDM1.SETTEIATAI = TSSM.CUPHOLDERUMU WHERE TSSM.APKIHONCD = #{itakuApKihonCd,jdbcType=VARCHAR} AND TSSM.SHOPCD = #{itakuShopCd,jdbcType=VARCHAR} AND TSSM.TOKUISAKICD = #{itakuTokuisakiCd,jdbcType=VARCHAR} AND TSSM.YUKOKBN = '1' AND TSSM.HIKIAGEDD IS NULL
) TSM ORDER BY TSM.WSVKISHUCD, TSM.SHNCD, TSM.STUPWSVNO

SELECT * FROM ( SELECT BASE.APKIHONCD, BASE.SHOPCD, BASE.TOKUISAKICD, BASE.TOKUISAKINMN1, ( CASE WHEN BASE.KYUMINKBN != '0' THEN '休眠' ELSE NULL END ) KYUMINKBN, SKSM.TAIRYUKBN, CNDM.ITEMNM TAIRYUKBNNM, BASE.YUBINNO, BASE.ADRSN1, BASE.RENRAKUSAKINON1, BASE.SHNCD, SHMV.GENZSHNNMRYAKUSHO GENZSHNNM, SHMV.SHINSHNNMRYAKUSHO SHINSHNNM, SHMV.SHNNMKIRIKAEDD, SYKM.MOJISETTEIATAI KEIJOKBNNM, BASE.JIKAIMNTYTIDYDM, BASE.YTIDAISU, ( SELECT COUNT(0) FROM S02M048T TSSM2, S02M013T TKSM2 WHERE TKSM2.APKIHONCD = BASE.APKIHONCD AND TKSM2.SHOPCD = BASE.SHOPCD AND TKSM2.TOKUISAKICD = BASE.TOKUISAKICD AND TSSM2.SHNCD = BASE.SHNCD AND ( ( TKSM2.APKIHONCD = TSSM2.APKIHONCD AND TKSM2.SHOPCD = TSSM2.SHOPCD AND TKSM2.TOKUISAKICD = TSSM2.TOKUISAKICD ) OR( TKSM2.ITAKUAITEAPKIHONCD = TSSM2.APKIHONCD AND TKSM2.ITAKUAITESHOPCD = TSSM2.SHOPCD AND TKSM2.ITAKUAITETOKUISAKICD = TSSM2.TOKUISAKICD ) ) AND TSSM2.HIKIAGEDD IS NULL AND TSSM2.YUKOKBN = '1' ) TOTALDAISU FROM ( SELECT TKSM.APKIHONCD, TKSM.SHOPCD, TKSM.TOKUISAKICD, TKSM.TOKUISAKINMN1, TKSM.KYUMINKBN, TKSM.YUBINNO, TKSM.ADRSN1, TKSM.RENRAKUSAKINON1, TKSM.SKYSAKICD, TSSM.SHNCD, TSSM.KEIJOKBN, TSSM.JIKAIMNTYTIDYDM, COUNT(*) YTIDAISU FROM S02M048T TSSM, S02M013T TKSM WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND ( ( TKSM.APKIHONCD = TSSM.APKIHONCD AND TKSM.SHOPCD = TSSM.SHOPCD AND TKSM.TOKUISAKICD = TSSM.TOKUISAKICD ) OR ( TKSM.ITAKUAITEAPKIHONCD = TSSM.APKIHONCD AND TKSM.ITAKUAITESHOPCD = TSSM.SHOPCD AND TKSM.ITAKUAITETOKUISAKICD = TSSM.TOKUISAKICD ) ) AND TKSM.YUKOKBN = '1' AND TSSM.HIKIAGEDD IS NULL AND TSSM.JIKAIMNTYTIDYDM BETWEEN #{dydmstr,jdbcType=VARCHAR} AND #{dydmend,jdbcType=VARCHAR} AND TSSM.YUKOKBN = '1' AND TKSM.TOKUISAKIKBN IN ('1', '5', '6')
AND TKSM.EIGYOTNSHACD = #{eigyotnshacd,jdbcType=VARCHAR}
AND TKSM.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR}
AND TKSM.DLVRYKANKATSUAPKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUSHOPCD = #{shopcd,jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUKYOTENCD = #{dlvrykankatsukyotencd,jdbcType=VARCHAR}
AND TKSM.EIGYOAREACD IN
#{item,jdbcType=VARCHAR}
AND TKSM.DLVRYAREACD IN
#{item,jdbcType=VARCHAR}
AND TSSM.SHNCD = #{shncd,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND TKSM.JUTAKUDLVRYCSTKBN IN
#{item,jdbcType=VARCHAR}
AND TSSM.FRONTPANELCD LIKE #{frontpanelcd,jdbcType=VARCHAR} || '%'
AND TSSM.WSVKISHUCD = #{wsvkishucd,jdbcType=VARCHAR}
GROUP BY TKSM.APKIHONCD, TKSM.SHOPCD, TKSM.TOKUISAKICD, TKSM.TOKUISAKINMN1, TKSM.KYUMINKBN, TKSM.YUBINNO, TKSM.ADRSN1, TKSM.RENRAKUSAKINON1, TKSM.SKYSAKICD, TSSM.SHNCD, TSSM.KEIJOKBN, TSSM.JIKAIMNTYTIDYDM ) BASE LEFT JOIN S02V001T SHMV ON BASE.APKIHONCD = SHMV.APKIHONCD AND BASE.SHOPCD = SHMV.SHOPCD AND BASE.SHNCD = SHMV.SHNCD LEFT JOIN S02M006T SYKM ON SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '009' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEICD = BASE.KEIJOKBN LEFT JOIN S02M017T SKSM ON SKSM.APKIHONCD = BASE.APKIHONCD AND SKSM.SHOPCD = BASE.SHOPCD AND SKSM.SKYSAKICD = BASE.SKYSAKICD LEFT JOIN S01M004T CNDM ON CNDM.SETTEIATAI = SKSM.TAIRYUKBN AND CNDM.CONDITIONID ='CN085' ORDER BY BASE.TOKUISAKICD, BASE.SHNCD, BASE.JIKAIMNTYTIDYDM ) WHERE ROWNUM <= #{rownum,jdbcType=VARCHAR} + 1

SELECT TTSSM.SHNCD, TTSSM.SRLNO, TTSSM.STUPDD, TTSSM.KONKAIMNTDD AS ZNKMNTDD, TTSSM.JIKAIMNTYTIDYDM, TTSSM.CUPHOLDERUMU, SYKM.MOJISETTEIATAI AS LOCKTFOSETMEI FROM S02M048T TTSSM LEFT OUTER JOIN S02M006T SYKM ON( SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '144' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEICD = TTSSM.LOCKTFOSET ) WHERE TTSSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TTSSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TTSSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND TTSSM.SRLNO = #{srlno,jdbcType=VARCHAR}
AND TTSSM.HIKIAGEDD IS NULL AND TTSSM.YUKOKBN = '1' AND TTSSM.STUPDD = ( SELECT NVL(MAX(TTSSM2.STUPDD), 0) FROM S02M048T TTSSM2 WHERE TTSSM2.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TTSSM2.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TTSSM2.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} AND TTSSM2.HIKIAGEDD IS NULL AND TTSSM2.YUKOKBN = '1' )

SELECT TSSM.APKIHONCD , TSSM.SHOPCD , TSSM.TOKUISAKICD , TSSM.SRLNO , TSSM.SHNCD , SHMV.SHINSHNNM , SHMV.GENZSHNNM , SHMV.SHNNMKIRIKAEDD , TSSM.MEISAIBIKO FROM S02M048T TSSM LEFT JOIN S02V001T SHMV ON TSSM.APKIHONCD = SHMV.APKIHONCD AND TSSM.SHOPCD = SHMV.SHOPCD AND TSSM.SHNCD = SHMV.SHNCD WHERE (( TSSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TSSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TSSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} )
OR( TSSM.APKIHONCD = #{itakuaiteapkihoncd,jdbcType=VARCHAR} AND TSSM.SHOPCD = #{itakuaiteshopcd,jdbcType=VARCHAR} AND TSSM.TOKUISAKICD = #{itakuaitetokuisakicd,jdbcType=VARCHAR} )
) AND TSSM.HIKIAGEDD IS NULL AND TSSM.YUKOKBN = '1' ORDER BY TSSM.STUPDD , TSSM.SRLNO

SELECT TSSM.JIKAIMNTYTIDYDM JIKAIMNTYTIDYDM, TSSM.KONKAIMNTDD ZNKMNTDD, TKSM.APKIHONCD, TKSM.SHOPCD, TSSM.APKIHONCD TSSM_APKIHONCD, TSSM.SHOPCD TSSM_SHOPCD, TSSM.TOKUISAKICD TSSM_TOKUISAKICD, TKSM.TOKUISAKICD TOKUISAKICD, TKSM.TOKUISAKINMN1 TOKUISAKINMN1, TKSM.TOKUISAKINMN2 TOKUISAKINMN2, TKSM.TOKUISAKINMKANAN1 TOKUISAKINMKANAN1, TKSM.TOKUISAKINMKANAN2 TOKUISAKINMKANAN2, TKSM.TOKUISAKIKEISHOKBN TOKUISAKIKEISHOKBN, TKSM.YUBINNO YUBINNO, TKSM.ADRSN1 ADRSN1, TKSM.ADRSN2 ADRSN2, TKSM.ADRSN3 ADRSN3, SYKM1.MOJISETTEIATAI RENRAKUSAKINONM1, TKSM.RENRAKUSAKINON1 RENRAKUSAKINON1, SYKM2.MOJISETTEIATAI RENRAKUSAKINONM2, TKSM.RENRAKUSAKINON2 RENRAKUSAKINON2, SYKM3.MOJISETTEIATAI RENRAKUSAKINONM3, TKSM.RENRAKUSAKINON3 RENRAKUSAKINON3, SYKM4.MOJISETTEIATAI RENRAKUSAKINONM4, TKSM.RENRAKUSAKINON4 RENRAKUSAKINON4, SYKM5.MOJISETTEIATAI TOKUISAKIJOTAINM, SYKM6.MOJISETTEIATAI JOTAISTSNM, TKSM.JUTAKUDLVRYCSTKBN JUTAKUDLVRYCSTKBN, TKSM.TOKUISAKISHOPCD, SHPM2.SHOPNM AS TOKUISAKISHOPMEI, TKSM.JIGYOSHOCD, JGSM.JIGYOSHONM, SYKM7.MOJISETTEIATAI CDKINDKBNNM, SYKM8.MOJISETTEIATAI GYOSHUKBNNM, SYKM9.MOJISETTEIATAI CHUITOKUISAKIKBNAP, TKSM.CHUINAIYOAP, TKSM.SKYSAKICD, SKSM.SKYSAKINMN1, SKSM.SKYSAKINMN2, SKSM.SKYKBN, SKSM.KAISHUHOHOKBN, SKSM.SHRSAITO, SKSM.SHRDD, (CASE WHEN TKSM.KYUMINKBN != '0' THEN '休眠' ELSE NULL END) KYUMINKBN, SKSM.TAIRYUKBN TAIRYUKBN, SKSM.TAIRYUKIN, TJST.GENZAIZD, TKSM.NYUKAIDD, TKSM.MOSHIKOMIRCPTKBN, TKSM.SHOKAIWSVSTUPDD, EGAM.EIGYOAREANM, TKSM.EIGYOTNSHACD, TTSM.TNSHAMEI EIGYOTNSHAMEI, TKSM.DLVRYKANKATSUAPKIHONCD, APKM.APNM, TKSM.DLVRYKANKATSUSHOPCD, SHPM.SHOPNM, TKSM.DLVRYKANKATSUKYOTENCD, HKNM.DLVRYKYOTENNM, HTAM.DLVRYAREANM, SYKM10.MOJISETTEIATAI DLVRYKBNNM, TKSM.DLVRYCMPNYCD, HTKM.DLVRYCMPNYNM, TKSM.DLVRYTNSHACD, TTSM2.TNSHAMEI DLVRYTNSHAMEI, TKSM.CHIZUNO, SYKM11.MOJISETTEIATAI NOHINSAKIJOHON1, SYKM12.MOJISETTEIATAI NOHINSAKIJOHON2, TJST.AZUKARIBTLN1N2RITTORUHNS, TJST.AZUKARIBTLN8RITTORUHNS, SYKM13.MOJISETTEIATAI KEIZOKURNK, SYKM14.MOJISETTEIATAI SHOHIRNK, SYKM15.MOJISETTEIATAI APBETSUTOKUISAKIRNK, TJST.SAISHUACPTDD, TJST.ZNKDLVRYDD, TJST.ZNKDLVRYRGRAYUSYOHNS + TJST.ZNKDLVRYSRMYUSYOHNS + TJST.ZNKDLVRYSONOTAYUSYOHNS AS YUSYOHNS, TJST.ZNKDLVRYRGRAMUSHOHNS + TJST.ZNKDLVRYSRMMUSHOHNS + TJST.ZNKDLVRYSONOTAMUSHOHNS AS MUSHOHNS, TSSM.SHNCD SHNCD, SHMV.GENZSHNNM GENZSHNNM, SHMV.SHINSHNNM SHINSHNNM, SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD, SHMV.IRO, SHMV.SZ, TSSM.KATASIKI, TSSM.SRLNO, SYKM.MOJISETTEIATAI KEIJOKBNNM, TSSM.STUPDD, TSSM.RTLSTRTDD, TSSM.CUPHOLDERUMU, SYKM16.MOJISETTEIATAI LOCKTFOSET, WSKM.KOKANYMDN1, SYKM17.MOJISETTEIATAI SENZYOSTSN1, SYKM18.MOJISETTEIATAI ONSUIFOSETN1, SYKM19.MOJISETTEIATAI REISUIFOSETN1, SYKM20.MOJISETTEIATAI KOKINPELETN1, SYKM21.MOJISETTEIATAI FILTERN1, WSKM.TANTOAPKIHONCDN1, WSKM.TANTOSHOPCDN1, WSKM.TNSHACDN1, TTSM3.TNSHAMEI, TSSM.RTLRKN, TSSM.MEISAIBIKO, TSSM.FRONTPANELCD, KSHM.GENZSHNNM PANELGENZSHNNM, KSHM.SHINSHNNM PANELSHINSHNNM, KSHM.SHNNMKIRIKAEDD PANELSHNNMKIRIKAEDD, TSSM.PANELNO, SYKM22.MOJISETTEIATAI WSVJOTAIRNK, WSKM.ACISABURTLSTRTDYDM, TKSM.TOKUISAKIKBN TOKUISAKIKBN, SYKM23.MOJISETTEIATAI GYOSHUSHSKBNMEI, WSKM.SHUKKADYDMDD SHUKKADYDMDD, SYKM25.MOJISETTEIATAI UNYODATE, WSKM.TAIYODYKAZU TAIYODYKAZU, SYKM24.MOJISETTEIATAI STUPBASYOKBNMEI, TSSM.STUPBASYOBIKO STUPBASYOBIKO FROM S02M048T TSSM INNER JOIN S02M013T TKSM ON ( ( TKSM.APKIHONCD = TSSM.APKIHONCD AND TKSM.SHOPCD = TSSM.SHOPCD AND TKSM.TOKUISAKICD = TSSM.TOKUISAKICD ) OR( TKSM.ITAKUAITEAPKIHONCD = TSSM.APKIHONCD AND TKSM.ITAKUAITESHOPCD = TSSM.SHOPCD AND TKSM.ITAKUAITETOKUISAKICD = TSSM.TOKUISAKICD ) ) LEFT JOIN S02V001T SHMV ON TSSM.APKIHONCD = SHMV.APKIHONCD AND TSSM.SHOPCD = SHMV.SHOPCD AND TSSM.SHNCD = SHMV.SHNCD LEFT JOIN S02M006T SYKM ON SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '009' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEICD = TSSM.KEIJOKBN LEFT JOIN S02M006T SYKM1 ON SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '011' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = TKSM.RENRAKUSAKINOKBNN1 LEFT JOIN S02M006T SYKM2 ON SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '011' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = TKSM.RENRAKUSAKINOKBNN2 LEFT JOIN S02M006T SYKM3 ON SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '011' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = TKSM.RENRAKUSAKINOKBNN3 LEFT JOIN S02M006T SYKM4 ON SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.SETTEINO = '011' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEICD = TKSM.RENRAKUSAKINOKBNN4 LEFT JOIN S02M006T SYKM5 ON SYKM5.APKIHONCD = '000' AND SYKM5.SHOPCD = '000' AND SYKM5.SETTEINO = '014' AND SYKM5.RCRDKBN = 'M' AND SYKM5.SETTEICD = TKSM.TOKUISAKIJOTAI LEFT JOIN S02M006T SYKM6 ON SYKM6.APKIHONCD = '000' AND SYKM6.SHOPCD = '000' AND SYKM6.SETTEINO = '015' AND SYKM6.RCRDKBN = 'M' AND SYKM6.SETTEICD = TKSM.JOTAISTS LEFT JOIN S02M047T JGSM ON JGSM.APKIHONCD = TKSM.APKIHONCD AND JGSM.SHOPCD = TKSM.SHOPCD AND JGSM.JIGYOSHOCD = TKSM.JIGYOSHOCD LEFT JOIN S02M006T SYKM7 ON SYKM7.APKIHONCD = '000' AND SYKM7.SHOPCD = '000' AND SYKM7.SETTEINO = '016' AND SYKM7.RCRDKBN = 'M' AND SYKM7.SETTEICD = TKSM.CDKINDKBN LEFT JOIN S02M006T SYKM8 ON SYKM8.APKIHONCD = '000' AND SYKM8.SHOPCD = '000' AND SYKM8.SETTEINO = '017' AND SYKM8.RCRDKBN = 'M' AND SYKM8.SETTEICD = TKSM.GYOSHUKBN LEFT JOIN S02M006T SYKM9 ON SYKM9.APKIHONCD = '000' AND SYKM9.SHOPCD = '000' AND SYKM9.SETTEINO = '017' AND SYKM9.RCRDKBN = 'M' AND SYKM9.SETTEICD = TKSM.CHUITOKUISAKIKBNAP LEFT JOIN S02M050T TJST ON TJST.APKIHONCD = TKSM.APKIHONCD AND TJST.SHOPCD = TKSM.SHOPCD AND TJST.TOKUISAKICD = TKSM.TOKUISAKICD LEFT JOIN S02M020T EGAM ON EGAM.APKIHONCD = TKSM.APKIHONCD AND EGAM.SHOPCD = TKSM.SHOPCD AND EGAM.EIGYOAREACD = TKSM.EIGYOAREACD LEFT JOIN S02M003T TTSM ON TTSM.APKIHONCD = TKSM.APKIHONCD AND TTSM.SHOPCD = TKSM.SHOPCD AND TTSM.TNSHACD = TKSM.EIGYOTNSHACD LEFT JOIN S02M001T APKM ON APKM.APKIHONCD = TKSM.DLVRYKANKATSUAPKIHONCD LEFT JOIN S02M046T SHPM ON SHPM.APKIHONCD = TKSM.DLVRYKANKATSUAPKIHONCD AND SHPM.SHOPCD = TKSM.DLVRYKANKATSUSHOPCD LEFT JOIN S02M046T SHPM2 ON SHPM2.APKIHONCD = TKSM.APKIHONCD AND SHPM2.SHOPCD = TKSM.TOKUISAKISHOPCD LEFT JOIN S02M011T WSKM ON WSKM.SRLNO = TSSM.SRLNO LEFT JOIN S02M003T TTSM3 ON TTSM3.APKIHONCD = WSKM.TANTOAPKIHONCDN1 AND TTSM3.SHOPCD = WSKM.TANTOSHOPCDN1 AND TTSM3.TNSHACD = WSKM.TNSHACDN1 LEFT JOIN S02M006T SYKM16 ON SYKM16.APKIHONCD = '000' AND SYKM16.SHOPCD = '000' AND SYKM16.SETTEINO = '144' AND SYKM16.RCRDKBN = 'M' AND SYKM16.SETTEICD = TSSM.LOCKTFOSET LEFT JOIN S02M006T SYKM17 ON SYKM17.APKIHONCD = '000' AND SYKM17.SHOPCD = '000' AND SYKM17.SETTEINO = '112' AND SYKM17.RCRDKBN = 'M' AND SYKM17.SETTEICD = WSKM.SENZYOSTSN1 LEFT JOIN S02M006T SYKM18 ON SYKM18.APKIHONCD = '000' AND SYKM18.SHOPCD = '000' AND SYKM18.SETTEINO = '911' AND SYKM18.RCRDKBN = 'M' AND SYKM18.SETTEICD = WSKM.ONSUIFOSETN1 LEFT JOIN S02M006T SYKM19 ON SYKM19.APKIHONCD = '000' AND SYKM19.SHOPCD = '000' AND SYKM19.SETTEINO = '912' AND SYKM19.RCRDKBN = 'M' AND SYKM19.SETTEICD = WSKM.REISUIFOSETN1 LEFT JOIN S02M006T SYKM20 ON SYKM20.APKIHONCD = '000' AND SYKM20.SHOPCD = '000' AND SYKM20.SETTEINO = '913' AND SYKM20.RCRDKBN = 'M' AND SYKM20.SETTEICD = WSKM.KOKINPELETN1 LEFT JOIN S02M006T SYKM21 ON SYKM21.APKIHONCD = '000' AND SYKM21.SHOPCD = '000' AND SYKM21.SETTEINO = '914' AND SYKM21.RCRDKBN = 'M' AND SYKM21.SETTEICD = WSKM.FILTERN1 LEFT JOIN S02M031T HKNM ON HKNM.APKIHONCD = TKSM.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = TKSM.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = TKSM.DLVRYKANKATSUKYOTENCD LEFT JOIN S02M018T HTAM ON HTAM.APKIHONCD = TKSM.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = TKSM.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = TKSM.DLVRYKANKATSUKYOTENCD AND HTAM.DLVRYAREACD = TKSM.DLVRYAREACD AND #{unyodd,jdbcType=VARCHAR} BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD LEFT JOIN S02M006T SYKM10 ON SYKM10.APKIHONCD = '000' AND SYKM10.SHOPCD = '000' AND SYKM10.SETTEINO = '029' AND SYKM10.RCRDKBN = 'M' AND SYKM10.SETTEICD = TKSM.DLVRYKBN LEFT JOIN S02M019T HTKM ON HTKM.APKIHONCD = TKSM.APKIHONCD AND HTKM.SHOPCD = TKSM.SHOPCD AND HTKM.DLVRYCMPNYCD = TKSM.DLVRYCMPNYCD LEFT JOIN S02M003T TTSM2 ON TTSM2.APKIHONCD = TKSM.APKIHONCD AND TTSM2.SHOPCD = TKSM.SHOPCD AND TTSM2.TNSHACD = TKSM.DLVRYTNSHACD LEFT JOIN S02M006T SYKM11 ON SYKM11.APKIHONCD = '000' AND SYKM11.SHOPCD = '000' AND SYKM11.SETTEINO = '056' AND SYKM11.RCRDKBN = 'M' AND SYKM11.SETTEICD = TKSM.NOHINSAKIJOHON1 LEFT JOIN S02M006T SYKM12 ON SYKM12.APKIHONCD = '000' AND SYKM12.SHOPCD = '000' AND SYKM12.SETTEINO = '057' AND SYKM12.RCRDKBN = 'M' AND SYKM12.SETTEICD = TKSM.NOHINSAKIJOHON2 LEFT JOIN S02M006T SYKM13 ON SYKM13.APKIHONCD = '000' AND SYKM13.SHOPCD = '000' AND SYKM13.SETTEINO = '069' AND SYKM13.RCRDKBN = 'M' AND SYKM13.SETTEICD = TKSM.KEIZOKURNK LEFT JOIN S02M006T SYKM14 ON SYKM14.APKIHONCD = '000' AND SYKM14.SHOPCD = '000' AND SYKM14.SETTEINO = '070' AND SYKM14.RCRDKBN = 'M' AND SYKM14.SETTEICD = TKSM.SHOHIRNK LEFT JOIN S02M006T SYKM15 ON SYKM15.APKIHONCD = '000' AND SYKM15.SHOPCD = '000' AND SYKM15.SETTEINO = '023' AND SYKM15.RCRDKBN = 'M' AND SYKM15.SETTEICD = TKSM.APBETSUTOKUISAKIRNK LEFT JOIN S02M017T SKSM ON SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD LEFT JOIN S02M006T SYKM22 ON SYKM22.APKIHONCD = '000' AND SYKM22.SHOPCD = '000' AND SYKM22.SETTEINO = '080' AND SYKM22.RCRDKBN = 'M' AND SYKM22.SETTEICD = WSKM.WSVJOTAIRNK LEFT JOIN S02M007T KSHM ON KSHM.APKIHONCD = '001' AND KSHM.SHNCD = TSSM.FRONTPANELCD LEFT JOIN S02M006T SYKM23 ON SYKM23.APKIHONCD = '000' AND SYKM23.SHOPCD = '000' AND SYKM23.OYASETTEINO = '017' AND SYKM23.OYASETTEICD = TKSM.GYOSHUKBN AND SYKM23.SETTEINO = '185' AND SYKM23.RCRDKBN = 'M' AND SYKM23.SETTEICD = TKSM.GYOSHUSHSKBN AND SYKM23.YUKOKBN = '1' LEFT JOIN S02M006T SYKM24 ON SYKM24.APKIHONCD = '000' AND SYKM24.SHOPCD = '000' AND SYKM24.SETTEINO = '184' AND SYKM24.RCRDKBN = 'M' AND SYKM24.SETTEICD = TSSM.STUPBASYOKBN AND SYKM24.YUKOKBN = '1' LEFT JOIN S02M006T SYKM25 ON SYKM25.APKIHONCD = TSSM.APKIHONCD AND SYKM25.SHOPCD= TSSM.SHOPCD AND SYKM25.SETTEINO= '038' AND SYKM25.RCRDKBN = 'M' AND SYKM25.YUKOKBN = '1'
WHERE TKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TSSM.HIKIAGEDD IS NULL AND TSSM.JIKAIMNTYTIDYDM BETWEEN #{dydmstr,jdbcType=VARCHAR} AND #{dydmend,jdbcType=VARCHAR} AND TSSM.YUKOKBN = '1' AND TKSM.TOKUISAKIKBN IN ('1', '5', '6')
AND TKSM.EIGYOTNSHACD = #{eigyotnshacd,jdbcType=VARCHAR}
AND TKSM.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR}
AND TKSM.DLVRYKANKATSUAPKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUSHOPCD = #{shopcd,jdbcType=VARCHAR} AND TKSM.DLVRYKANKATSUKYOTENCD = #{dlvrykankatsukyotencd,jdbcType=VARCHAR}
AND TKSM.EIGYOAREACD IN
#{item,jdbcType=VARCHAR}
AND TKSM.DLVRYAREACD IN
#{item,jdbcType=VARCHAR}
AND TSSM.SHNCD = #{shncd,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND TKSM.JUTAKUDLVRYCSTKBN IN
#{item,jdbcType=VARCHAR}
AND TSSM.FRONTPANELCD LIKE #{frontpanelcd,jdbcType=VARCHAR} || '%'
AND TSSM.WSVKISHUCD = #{wsvkishucd,jdbcType=VARCHAR}
ORDER BY TKSM.APKIHONCD, TKSM.SHOPCD, TKSM.TOKUISAKICD, TSSM.SHNCD, TSSM.JIKAIMNTYTIDYDM

SELECT TSSTUPSV_MST.APKIHONCD AS APKIHONCD ,TSSTUPSV_MST.SHOPCD AS SHOPCD ,TSSTUPSV_MST.TOKUISAKICD AS TOKUISAKICD ,TSSTUPSV_MST.STUPWSVNO AS STUPWSVNO ,TSSTUPSV_MST.SHNCD AS SHNCD ,TSSTUPSV_MST.KATASIKI AS KATASIKI ,TSSTUPSV_MST.SRLNO AS SRLNO ,TSSTUPSV_MST.KEIJOKBN AS KEIJOKBN ,TSSTUPSV_MST.STUPDD AS STUPDD ,TSSTUPSV_MST.STUPNAIYO AS STUPNAIYO ,TSSTUPSV_MST.STUPMONOCD AS STUPMONOCD ,TSSTUPSV_MST.RTLSTRTDD AS RTLSTRTDD ,TSSTUPSV_MST.RTLRKN AS RTLRKN ,TSSTUPSV_MST.KONKAIMNTDD AS KONKAIMNTDD ,TSSTUPSV_MST.ZNKMNTDD AS ZNKMNTDD ,TSSTUPSV_MST.JIKAIMNTYTIDYDM AS JIKAIMNTYTIDYDM ,TSSTUPSV_MST.MNTKAISU AS MNTKAISU ,TSSTUPSV_MST.HIKIAGEDD AS HIKIAGEDD ,TSSTUPSV_MST.HIKIAGENAIYO AS HIKIAGENAIYO ,TSSTUPSV_MST.HIKIAGEDDTOSHACD AS HIKIAGEDDTOSHACD ,TSSTUPSV_MST.HIKIAGESOKOCD AS HIKIAGESOKOCD ,TSSTUPSV_MST.MEISAIBIKO AS MEISAIBIKO ,TSSTUPSV_MST.YUKOKBN AS YUKOKBN ,TSSTUPSV_MST.INPTSYSTMYMD AS INPTSYSTMYMD ,TSSTUPSV_MST.INPTSYSTMJIKAN AS INPTSYSTMJIKAN ,TSSTUPSV_MST.KSHNSYSTMYMD AS KSHNSYSTMYMD ,TSSTUPSV_MST.KSHNSYSTMJIKAN AS KSHNSYSTMJIKAN ,TSSTUPSV_MST.CUPHOLDERUMU AS CUPHOLDERUMU ,TSSTUPSV_MST.SOKOSHOPCD AS SOKOSHOPCD ,TSSTUPSV_MST.SOKOCD AS SOKOCD ,TSSTUPSV_MST.HIKIAGESOKOSHOPCD AS HIKIAGESOKOSHOPCD ,TSSTUPSV_MST.TNSHACDN1 AS TNSHACDN1 ,TSSTUPSV_MST.TNSHACDN2 AS TNSHACDN2 ,TSSTUPSV_MST.TNSHACDN3 AS TNSHACDN3 ,SOKO_MST2.SOKONMN1 AS SOKONM_SETTI ,TANSHA_MST_KONKAI.TNSHAMEI AS TNSHANMN1 ,TANSHA_MST_ZENKAI.TNSHAMEI AS TNSHANMN2 ,TANSHA_MST_ZENZENKAI.TNSHAMEI AS TNSHANMN3 ,TSSTUPSV_MST.TOSHAAPKIHONCD AS TOSHAAPKIHONCD ,TSSTUPSV_MST.TOSHASHOPCD AS TOSHASHOPCD ,TSSTUPSV_MST.TOSHACD AS TOSHACD ,TANSHA_MST_TOSHACD.TNSHAMEI AS TOSHANM ,TSSTUPSV_MST.KOSHAAPKIHONCD AS KOSHAAPKIHONCD ,TSSTUPSV_MST.KOSHASHOPCD AS KOSHASHOPCD ,TSSTUPSV_MST.KOSHACD AS KOSHACD ,TANSHA_MST_KOSHACD.TNSHAMEI AS KOSHANM ,TSSTUPSV_MST.LOCKTFOSET AS LOCKTFOSET ,SHN_MST_V.GENZSHNNMRYAKUSHO AS GENZSHNNM ,SHN_MST_V.SHINSHNNMRYAKUSHO AS SHINSHNNM ,SHN_MST_V.SHNNMKIRIKAEDD AS SHNNMKIRIKAEDD ,SHN_MST_V.IRO AS IRO ,SYSKNR_MST_SZ.MOJISETTEIATAI AS SZ ,TANSHA_MST_STUP.TNSHAMEI AS STUPTOROKUSHAMEI ,TANSHA_MST_HIKIAGE.TNSHAMEI AS HIKIAGETOROKUSHAMEI ,SOKO_MST.SOKONMN1 AS SOKONMN1 ,TSSTUPSV_MST.SABUSTS AS SABUSTS ,TSSTUPSV_MST.MNTKANKAKU AS MNTKANKAKU ,TSSTUPSV_MST.PANELNO AS PANELNO ,TSSTUPSV_MST.FRONTPANELCD AS FRONTPANELCD ,TSSTUPSV_MST.STUPBASYOKBN AS STUPBASYOKBN ,TSSTUPSV_MST.STUPBASYOBIKO AS STUPBASYOBIKO FROM S02M048T TSSTUPSV_MST LEFT OUTER JOIN S02V001T SHN_MST_V ON( TSSTUPSV_MST.APKIHONCD = SHN_MST_V.APKIHONCD AND TSSTUPSV_MST.SHOPCD = SHN_MST_V.SHOPCD AND TSSTUPSV_MST.SHNCD = SHN_MST_V.SHNCD ) LEFT OUTER JOIN S02M003T TANSHA_MST_STUP ON( TSSTUPSV_MST.APKIHONCD = TANSHA_MST_STUP.APKIHONCD AND TSSTUPSV_MST.SHOPCD = TANSHA_MST_STUP.SHOPCD AND TSSTUPSV_MST.STUPMONOCD = TANSHA_MST_STUP.TNSHACD ) LEFT OUTER JOIN S02M003T TANSHA_MST_HIKIAGE ON( TSSTUPSV_MST.HIKIAGEDDTOSHAAPKIHONCD = TANSHA_MST_HIKIAGE.APKIHONCD AND TSSTUPSV_MST.HIKIAGEDDTOSHASHOPCD = TANSHA_MST_HIKIAGE.SHOPCD AND TSSTUPSV_MST.HIKIAGEDDTOSHACD = TANSHA_MST_HIKIAGE.TNSHACD ) LEFT OUTER JOIN S02M041T SOKO_MST ON( TSSTUPSV_MST.HIKIAGESOKOAPKIHONCD = SOKO_MST.APKIHONCD AND TSSTUPSV_MST.HIKIAGESOKOSHOPCD = SOKO_MST.SHOPCD AND TSSTUPSV_MST.HIKIAGESOKOCD = SOKO_MST.SOKOCD ) LEFT OUTER JOIN S02M011T WSVSRL_MST ON( TSSTUPSV_MST.SRLNO = WSVSRL_MST.SRLNO ) LEFT OUTER JOIN S02M006T SYSKNR_MST_SZ ON( SYSKNR_MST_SZ.APKIHONCD = '000' AND SYSKNR_MST_SZ.SHOPCD = '000' AND SYSKNR_MST_SZ.SETTEINO = '037' AND SYSKNR_MST_SZ.RCRDKBN = 'M' AND SYSKNR_MST_SZ.SETTEICD = SHN_MST_V.SZ ) LEFT OUTER JOIN S02M003T TANSHA_MST_KONKAI ON( TSSTUPSV_MST.TANTOAPKIHONCDN1 = TANSHA_MST_KONKAI.APKIHONCD AND TSSTUPSV_MST.TANTOSHOPCDN1 = TANSHA_MST_KONKAI.SHOPCD AND TSSTUPSV_MST.TNSHACDN1 = TANSHA_MST_KONKAI.TNSHACD ) LEFT OUTER JOIN S02M003T TANSHA_MST_ZENKAI ON( TSSTUPSV_MST.TANTOAPKIHONCDN2 = TANSHA_MST_ZENKAI.APKIHONCD AND TSSTUPSV_MST.TANTOSHOPCDN2 = TANSHA_MST_ZENKAI.SHOPCD AND TSSTUPSV_MST.TNSHACDN2 = TANSHA_MST_ZENKAI.TNSHACD ) LEFT OUTER JOIN S02M003T TANSHA_MST_ZENZENKAI ON( TSSTUPSV_MST.TANTOAPKIHONCDN3 = TANSHA_MST_ZENZENKAI.APKIHONCD AND TSSTUPSV_MST.TANTOSHOPCDN3 = TANSHA_MST_ZENZENKAI.SHOPCD AND TSSTUPSV_MST.TNSHACDN3 = TANSHA_MST_ZENZENKAI.TNSHACD ) LEFT OUTER JOIN S02M003T TANSHA_MST_TOSHACD ON( TSSTUPSV_MST.TOSHAAPKIHONCD = TANSHA_MST_TOSHACD.APKIHONCD AND TSSTUPSV_MST.TOSHASHOPCD = TANSHA_MST_TOSHACD.SHOPCD AND TSSTUPSV_MST.TOSHACD = TANSHA_MST_TOSHACD.TNSHACD ) LEFT OUTER JOIN S02M003T TANSHA_MST_KOSHACD ON( TSSTUPSV_MST.KOSHAAPKIHONCD = TANSHA_MST_KOSHACD.APKIHONCD AND TSSTUPSV_MST.KOSHASHOPCD = TANSHA_MST_KOSHACD.SHOPCD AND TSSTUPSV_MST.KOSHACD = TANSHA_MST_KOSHACD.TNSHACD ) LEFT OUTER JOIN S02M041T SOKO_MST2 ON( TSSTUPSV_MST.SOKOAPKIHONCD = SOKO_MST2.APKIHONCD AND TSSTUPSV_MST.SOKOSHOPCD = SOKO_MST2.SHOPCD AND TSSTUPSV_MST.SOKOCD = SOKO_MST2.SOKOCD ) WHERE TSSTUPSV_MST.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TSSTUPSV_MST.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TSSTUPSV_MST.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND TSSTUPSV_MST.YUKOKBN = '1'
AND TSSTUPSV_MST.YUKOKBN = '0'
AND TSSTUPSV_MST.HIKIAGEDD IS NULL
AND TSSTUPSV_MST.HIKIAGEDD IS NOT NULL
AND TSSTUPSV_MST.SRLNO LIKE '%' || #{srlno,jdbcType=VARCHAR} || '%'
AND TSSTUPSV_MST.KSHNSYSTMYMD = #{kshnsystmymd,jdbcType=VARCHAR}
AND TSSTUPSV_MST.KSHNSYSTMJIKAN = #{kshnsystmjikan,jdbcType=VARCHAR}
ORDER BY TSSTUPSV_MST.STUPDD DESC, TSSTUPSV_MST.STUPWSVNO DESC
